INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l25','reduce ... to','',NULL,'/rɪˈduːs tuː/','Constant stress reduced her to tears.','持续的压力让她落泪。','The fire reduced the house to ashes.','大火把房子烧成了灰烬。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l25','be cautious about','',NULL,'/biː ˈkɔːʃəs əˈbaʊt/','We should be cautious about such claims.','我们对这类说法应持谨慎态度。','Be cautious about believing rumors.','别轻信谣言。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l25','in case of','',NULL,'/ɪn keɪs ʌv/','In case of noise, a large study is needed.','碰到噪声问题,需要做大样本研究。','In case of fire, use the stairs.','万一失火,请走楼梯。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l25','turn to','',NULL,'/tɜːrn tuː/','On turning to the text, the reader learns the truth.','翻到正文,读者才知道真相。','She turned to the next chapter.','她翻到了下一章。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp1','choice','{"stem":"\"___ psychiatric interviews nor objective tests found any effect.\"(‘既不…也不…’结构的前一半,与后面的 nor 呼应)","options":["Not","Both","Either","Neither"],"answer_index":3,"stem_cn":"精神科访谈和客观测试都没发现任何影响。","explanation_cn":"‘既不…也不…’结构的前一半,与后面的 nor 呼应,用 Neither。✓ Neither interviews nor tests found … ✗ Either(与 or 搭配)/ Both / Not:与 nor 呼应用 Neither。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp1','choice','{"stem":"\"Neither the noise ___ the long hours harmed the sailors.\"(‘既不…也不…’结构的后一半,与前面呼应的那个词)","options":["nor","or","but","and"],"answer_index":0,"stem_cn":"噪声和长时间工作都没伤害到水兵。","explanation_cn":"‘既不…也不…’结构的后一半,与前面 Neither 呼应,用 nor。✓ Neither the noise nor the long hours … ✗ or / and / but:与 Neither 呼应用 nor。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp1','choice','{"stem":"\"Neither the doctors nor the machine ___ able to show harm.\"(neither…nor 连接,动词与靠近的 machine 一致,用单数)","options":["are","were","was","being"],"answer_index":2,"stem_cn":"医生和仪器都无法证明有害。","explanation_cn":"neither A nor B 连接,动词与靠近的 the machine 一致,用单数 was。✓ Neither the doctors nor the machine was able … ✗ were(复数)/ are(时态)/ being:就近一致用 was。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp2','choice','{"stem":"\"The study ___ as Project Anehin examined naval crews.\"(过去分词作后置定语,‘被称为…’,填‘称为’那个动词的过去分词)","options":["knowing","known","to know","knew"],"answer_index":1,"stem_cn":"那项名为‘阿内欣计划’的研究考察了海军人员。","explanation_cn":"过去分词作后置定语,表被动‘被称为’;此处填‘称为’那个动词的过去分词 known。✓ the study known as Project Anehin. ✗ knowing(主动)/ knew / to know:后置被动定语用过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp2','choice','{"stem":"\"An allegation often ___ is that noise causes illness.\"(过去分词作后置定语,被动‘被提出的’,填‘提出/做出’那个动词的过去分词)","options":["made","making","to make","makes"],"answer_index":0,"stem_cn":"一种常被提出的指控是:噪声会致病。","explanation_cn":"过去分词作后置定语,表被动‘被提出的’;填‘提出/做出’那个动词的过去分词 made。✓ an allegation often made. ✗ making(主动)/ makes / to make:后置被动定语用过去分词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp2','choice','{"stem":"\"Tests ___ under noisy conditions showed no effect.\"(过去分词作后置定语,被动‘被进行的’,填‘进行’那个动词的过去分词)","options":["conducting","to conduct","conducts","conducted"],"answer_index":3,"stem_cn":"在噪声环境下进行的测试没显示任何影响。","explanation_cn":"过去分词作后置定语,表被动‘被进行的’;填‘进行’那个动词的过去分词 conducted。✓ tests conducted under noisy conditions. ✗ conducting(主动)/ conducts / to conduct:后置被动定语用过去分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp3','choice','{"stem":"\"We must discover ___ they are mentally ill more often.\"(discover 后‘是否’的从句,填连词)","options":["whether","what","that","which"],"answer_index":0,"stem_cn":"我们必须查明他们是否更常患精神疾病。","explanation_cn":"discover 后接‘是否’的从句,用连词 whether。✓ discover whether they are ill … ✗ that / what / which:‘是否’用 whether。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp3','choice','{"stem":"\"Scientists asked ___ noise really affects the mind.\"(ask 后‘是否’的从句,填连词)","options":["how","whether","what","that"],"answer_index":1,"stem_cn":"科学家们发问:噪声是否真的影响心智。","explanation_cn":"ask 后接‘是否’的从句,用 whether。✓ asked whether noise affects the mind. ✗ that / what / how:‘是否’用 whether。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp3','choice','{"stem":"\"No one could say ___ the typist''s fear came from noise.\"(say 后‘是否’的从句,填连词)","options":["what","that","which","whether"],"answer_index":3,"stem_cn":"没人能说清那打字员的恐惧是否源自噪声。","explanation_cn":"say 后接‘是否’的从句,用 whether。✓ say whether the fear came from noise. ✗ that / what / which:‘是否’用 whether。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp4','choice','{"stem":"\"The snag in the anecdote is ___ it proves nothing.\"(is 后的从句作表语,只起引导作用,填连词)","options":["what","that","which","whether"],"answer_index":1,"stem_cn":"这则轶事的毛病在于:它什么也证明不了。","explanation_cn":"is 后的从句作表语,只起引导作用、本身无词义,用 that。✓ The snag is that it proves nothing. ✗ what(要在从句里作成分)/ which / whether:此处用 that。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp4','choice','{"stem":"\"One allegation is ___ noise produces mental illness.\"(is 后的从句作表语,填连词)","options":["that","what","which","how"],"answer_index":0,"stem_cn":"一种指控是:噪声会引发精神疾病。","explanation_cn":"is 后的从句作表语,用 that。✓ One allegation is that noise produces illness. ✗ what / which / how:此处用 that。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp4','choice','{"stem":"\"The truth is ___ we need to study large numbers of people.\"(is 后的从句作表语,填连词)","options":["which","that","whether","what"],"answer_index":1,"stem_cn":"事实是:我们需要研究大量的人。","explanation_cn":"is 后的从句作表语,用 that。✓ The truth is that we need to study large numbers. ✗ what / which / whether:此处用 that。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp5','choice','{"stem":"\"Noise may be ___ dangerous than a stressful childhood.\"(‘不如…那么危险’,填表‘更少’的那个词)","options":["less","little","least","few"],"answer_index":0,"stem_cn":"噪声也许不如艰难的童年那么危险。","explanation_cn":"‘不如…那么危险’= less + 形容词 + than;表‘更少’的词是 less。✓ less dangerous than a stressful childhood. ✗ least(最高级)/ little / few:比较用 less。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp5','choice','{"stem":"\"Sailors near jets suffer ___ noise than any of us.\"(‘更多的噪声’,much 的比较级)","options":["many","much","more","most"],"answer_index":2,"stem_cn":"喷气机旁的水兵承受的噪声比我们谁都多。","explanation_cn":"‘更多的噪声’;much(不可数)的比较级是 more。✓ suffer more noise than any of us. ✗ most(最高级)/ many(可数)/ much(原级):不可数比较级用 more。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp5','choice','{"stem":"\"For typing, a ___ office is better than a noisy one.\"(‘更安静的’,填 quiet 一词的比较级形式)","options":["quieter","quietest","quiet","more quiet"],"answer_index":0,"stem_cn":"打字时,安静的办公室比嘈杂的更好。","explanation_cn":"quiet 是双音节以 -t 结尾的形容词,比较级加 -er:quieter。✓ a quieter office is better than a noisy one. ✗ quietest(最高级)/ quiet(原级)/ more quiet:此处用 quieter。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp6','choice','{"stem":"\"A statement made without proof, accusing someone, is an ___.\"(“指控、断言”用哪个词)","options":["education","operation","invitation","allegation"],"answer_index":3,"stem_cn":"未经证实、指控他人的说法。","explanation_cn":"未经证实、指控他人的说法是 allegation(指控、断言)。✓ a statement made without proof is an allegation. ✗ invitation 邀请;✗ education 教育;✗ operation 手术/操作——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp6','choice','{"stem":"\"The identification of an illness by a doctor is a ___.\"(“诊断”用哪个词)","options":["diagnosis","distance","disguise","display"],"answer_index":0,"stem_cn":"医生对疾病的判定。","explanation_cn":"医生对疾病的判定是 diagnosis(诊断)。✓ the identification of an illness is a diagnosis. ✗ disguise 伪装;✗ distance 距离;✗ display 展示——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',5,'am4_l25_gp6','choice','{"stem":"\"The words printed under a picture are the ___.\"(“图片说明文字”用哪个词)","options":["capital","caption","chapter","carpet"],"answer_index":1,"stem_cn":"印在图片下方的文字。","explanation_cn":"印在图片下方的说明文字是 caption。✓ the words under a picture are the caption. ✗ chapter 章节;✗ capital 首都/资本;✗ carpet 地毯——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"auditory 的意思是:","options":["触觉的","听觉的","嗅觉的","视觉的"],"answer_index":1,"explanation_cn":"auditory = 听觉的。✓ not all of those effects are auditory."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"inadequate 的意思是:","options":["不充分的,不足的","精确的","明显的","充足的"],"answer_index":0,"explanation_cn":"inadequate = 不充分的、不足的。✓ is inadequate as proof."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"allegation 的意思是:","options":["证据","赞扬","结论","指控,断言"],"answer_index":3,"explanation_cn":"allegation = 指控、(无证据的)断言。✓ one allegation frequently made."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"anecdote 的意思是:","options":["数据","公式","轶事,趣闻","定理"],"answer_index":2,"explanation_cn":"anecdote = 轶事、趣闻。✓ this kind of anecdote."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"abatement 的意思是:","options":["减少,减轻","增加","持续","爆发"],"answer_index":0,"explanation_cn":"abatement = 减少、减轻。✓ noise abatement is a good cause."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',6,NULL,'choice','{"stem":"discredit 的意思是:","options":["证实","使不可信,不予采信","信任","赞美"],"answer_index":1,"explanation_cn":"discredit = 使不可信、不予采信。✓ discredit any firm conclusion."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',7,NULL,'cloze','{"stem":"第 1 空","context":"Many people say noise causes mental illness, but such an ___1___ is hard to prove. ___2___ psychiatric interviews nor objective tests found any effect on the sailors. What we need is to discover ___3___ noisy conditions really make people ill. The truth is ___4___ only a large study can settle the question.","blank_no":1,"options":["allegation","invitation","operation","education"],"answer_index":0,"explanation_cn":"未经证实的指控/断言是 allegation。✓ such an allegation is hard to prove."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',7,NULL,'cloze','{"stem":"第 2 空","context":"Many people say noise causes mental illness, but such an ___1___ is hard to prove. ___2___ psychiatric interviews nor objective tests found any effect on the sailors. What we need is to discover ___3___ noisy conditions really make people ill. The truth is ___4___ only a large study can settle the question.","blank_no":2,"options":["Neither","Either","Both","Not"],"answer_index":0,"explanation_cn":"与后面的 nor 呼应,前一半用 Neither。✓ Neither interviews nor tests found any effect."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',7,NULL,'cloze','{"stem":"第 3 空","context":"Many people say noise causes mental illness, but such an ___1___ is hard to prove. ___2___ psychiatric interviews nor objective tests found any effect on the sailors. What we need is to discover ___3___ noisy conditions really make people ill. The truth is ___4___ only a large study can settle the question.","blank_no":3,"options":["whether","that","what","which"],"answer_index":0,"explanation_cn":"discover 后接‘是否’的从句,用 whether。✓ discover whether noisy conditions make people ill."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',7,NULL,'cloze','{"stem":"第 4 空","context":"Many people say noise causes mental illness, but such an ___1___ is hard to prove. ___2___ psychiatric interviews nor objective tests found any effect on the sailors. What we need is to discover ___3___ noisy conditions really make people ill. The truth is ___4___ only a large study can settle the question.","blank_no":4,"options":["that","what","which","whether"],"answer_index":0,"explanation_cn":"is 后的从句作表语,用 that。✓ The truth is that only a large study can settle it."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',8,NULL,'choice','{"stem":"What conclusion does the author draw about noise and mental health?","options":["Noise clearly causes madness","Any effect is so small that current methods cannot detect it","Noise is the greatest health hazard","Noise has no effect on hearing"],"answer_index":1,"explanation_cn":"录音说:若噪声真影响心理健康,那影响也小到现有方法查不出来。✓ so small that methods cannot find it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',8,NULL,'choice','{"stem":"Why are anecdotes, like the story of the typist, not good evidence?","options":["A single case cannot prove that noise, not something else, caused the illness","They are always invented","They are too long to read","They come from newspapers"],"answer_index":0,"explanation_cn":"录音说:一则轶事无法证明是噪声、而非别的原因导致了疾病,所以不足为证。✓ one case cannot prove the cause."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',8,NULL,'choice','{"stem":"What did the study of aircraft-carrier crews find?","options":["The men all became ill","Noise improved their health","The study was never finished","Neither interviews nor tests could show any mental effect from the noise"],"answer_index":3,"explanation_cn":"录音说:海军研究里,无论访谈还是测试,都无法显示噪声对水兵心理有任何影响。✓ neither … nor … showed effect."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',9,NULL,'choice','{"stem":"你想说\"精神科访谈和客观测试都没发现任何影响\"(neither … nor …):","options":["Neither the interviews nor the tests found any effect.","Either the interviews nor the tests found any effect.","Neither the interviews nor the tests founds any effect.","Neither the interviews or the tests found any effect."],"answer_index":0,"explanation_cn":"Neither … nor 连接两者:后半用 nor(不用 or)、开头用 Neither(不用 Either)、动词就近一致 found(不写 founds)。✓ Neither … nor … found … 场合:说“两者都不…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',9,NULL,'choice','{"stem":"你想说\"我们必须查明他们是否更常患病\"(用 whether 引导‘是否’的从句):","options":["We must discover whether are they ill more often.","We must discover whether they are ill more often.","We must discover if or not they are ill more often.","We must discover that they are ill more often."],"answer_index":1,"explanation_cn":"discover 后接 whether 引导‘是否’的内容;用陈述语序 they are(不写 are they)、用 whether(不用 that)、‘是否’不说成 if or not。✓ discover whether they are ill … 场合:说“查明是否…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',9,NULL,'choice','{"stem":"你想说\"噪声也许不如艰难的童年那么危险\"(less … than):","options":["Noise may be less dangerous as a hard childhood.","Noise may be lesser dangerous than a hard childhood.","Noise may be less danger than a hard childhood.","Noise may be less dangerous than a hard childhood."],"answer_index":3,"explanation_cn":"less + 形容词 + than 表‘不如…那么…’;用 less(不用 lesser)、后接形容词 dangerous(不用名词 danger)、比较用 than(不用 as)。✓ less dangerous than … 场合:说“不如…那么…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"allegation 的意思是:","options":["证据","结论","赞扬","指控,断言"],"answer_index":3,"explanation_cn":"allegation = 指控、断言。✓ one allegation frequently made."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"auditory 的意思是:","options":["嗅觉的","视觉的","听觉的","触觉的"],"answer_index":2,"explanation_cn":"auditory = 听觉的。✓ not all of those effects are auditory."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"\"___ psychiatric interviews nor objective tests found any effect.\"(‘既不…也不…’的前一半,与 nor 呼应)","options":["Either","Not","Both","Neither"],"answer_index":3,"stem_cn":"精神科访谈和客观测试都没发现任何影响。","explanation_cn":"与后面的 nor 呼应,前一半用 Neither。✓ Neither interviews nor tests found any effect. ✗ Either / Both / Not。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"\"We must discover ___ noise really affects the mind.\"(discover 后‘是否’的从句)","options":["which","what","whether","that"],"answer_index":2,"stem_cn":"我们必须查明噪声是否真的影响心智。","explanation_cn":"discover 后接‘是否’的从句,用 whether。✓ discover whether noise affects the mind. ✗ that / what / which。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"\"in case of\" 的意思是:","options":["由于","除…之外","为了","在…情况下,万一"],"answer_index":3,"explanation_cn":"in case of = 在…情况下、万一。✓ in case of noise, a large study is needed."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"\"be cautious about\" 的意思是:","options":["对…持谨慎态度","对…厌恶","对…好奇","对…热衷"],"answer_index":0,"explanation_cn":"be cautious about = 对…持谨慎态度。✓ be cautious about such claims."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"According to the passage, what kind of study does the noise question really need?","options":["One newspaper article","A single dramatic anecdote","A study of large numbers of people living in noisy conditions","One patient''s complaint"],"answer_index":2,"passage":"People often argue about the effects of noise, and not all of those effects are auditory — that is, not all of them concern hearing itself. One allegation frequently made is that noise produces mental illness. A magazine once ran a dramatic picture of a distressed woman under the caption, ''Another victim, worn down to a nervous state.'' Turning to the text, the reader learned that the woman was a typist who found the clatter of office machines more and more upsetting, until at last she sought help at a psychiatric clinic. The snag in this kind of anecdote is that we cannot be sure the noise, rather than something else, was the real cause. A single story, however striking, is inadequate as proof, and a careful reader will discredit any firm conclusion drawn from it. What the question really needs is a study of large numbers of people living under noisy conditions, to discover whether they fall ill more often than others do. Some years ago a navy examined a great many men who worked on aircraft carriers, sharing the deck with squadron after squadron of jet aircraft — surely one of the noisiest workplaces on earth. Yet neither psychiatric interviews nor objective tests could show any mental effect of the noise upon these sailors. If noise harms mental health at all, the effect must be so small that present methods of diagnosis cannot find it. This does not prove that no effect exists; but it does suggest that the plea for a quieter world should rest on honest evidence, not on frightening pictures. Noise abatement is a good cause, and it is a pity to see it discredited by weak arguments. Noise may well be less dangerous than many other strains of modern life; the sensible course is to measure its effects carefully before we decide.","explanation_cn":"课文说:噪声问题真正需要的,是对大量生活在噪声环境中的人做研究,而非一则轶事。✓ study of large numbers."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"What does the author conclude from the naval study?","options":["If noise affects mental health at all, the effect is too small to measure","Sailors never hear the jets","Noise certainly drives sailors mad","Noise makes sailors healthier"],"answer_index":0,"passage":"People often argue about the effects of noise, and not all of those effects are auditory — that is, not all of them concern hearing itself. One allegation frequently made is that noise produces mental illness. A magazine once ran a dramatic picture of a distressed woman under the caption, ''Another victim, worn down to a nervous state.'' Turning to the text, the reader learned that the woman was a typist who found the clatter of office machines more and more upsetting, until at last she sought help at a psychiatric clinic. The snag in this kind of anecdote is that we cannot be sure the noise, rather than something else, was the real cause. A single story, however striking, is inadequate as proof, and a careful reader will discredit any firm conclusion drawn from it. What the question really needs is a study of large numbers of people living under noisy conditions, to discover whether they fall ill more often than others do. Some years ago a navy examined a great many men who worked on aircraft carriers, sharing the deck with squadron after squadron of jet aircraft — surely one of the noisiest workplaces on earth. Yet neither psychiatric interviews nor objective tests could show any mental effect of the noise upon these sailors. If noise harms mental health at all, the effect must be so small that present methods of diagnosis cannot find it. This does not prove that no effect exists; but it does suggest that the plea for a quieter world should rest on honest evidence, not on frightening pictures. Noise abatement is a good cause, and it is a pity to see it discredited by weak arguments. Noise may well be less dangerous than many other strains of modern life; the sensible course is to measure its effects carefully before we decide.","explanation_cn":"课文说:海军研究表明,若噪声影响心理,那影响也小到查不出来。✓ effect too small to find."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"Why is the story of the distressed typist weak as evidence?","options":["The newspaper lied","It was made up by the lady","Typists never work in offices","One case cannot prove noise, rather than something else, caused it"],"answer_index":3,"audio":"People often argue about the effects of noise, and not all of those effects are auditory — that is, not all of them concern hearing itself. One allegation frequently made is that noise produces mental illness. A magazine once ran a dramatic picture of a distressed woman under the caption, ''Another victim, worn down to a nervous state.'' Turning to the text, the reader learned that the woman was a typist who found the clatter of office machines more and more upsetting, until at last she sought help at a psychiatric clinic. The snag in this kind of anecdote is that we cannot be sure the noise, rather than something else, was the real cause. A single story, however striking, is inadequate as proof, and a careful reader will discredit any firm conclusion drawn from it. What the question really needs is a study of large numbers of people living under noisy conditions, to discover whether they fall ill more often than others do. Some years ago a navy examined a great many men who worked on aircraft carriers, sharing the deck with squadron after squadron of jet aircraft — surely one of the noisiest workplaces on earth. Yet neither psychiatric interviews nor objective tests could show any mental effect of the noise upon these sailors. If noise harms mental health at all, the effect must be so small that present methods of diagnosis cannot find it. This does not prove that no effect exists; but it does suggest that the plea for a quieter world should rest on honest evidence, not on frightening pictures. Noise abatement is a good cause, and it is a pity to see it discredited by weak arguments. Noise may well be less dangerous than many other strains of modern life; the sensible course is to measure its effects carefully before we decide.","explanation_cn":"课文说:那打字员的故事只是一例,无法证明是噪声、而非别的原因致病。✓ single case proves nothing."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l25',10,NULL,'choice','{"stem":"What did neither the interviews nor the tests manage to show?","options":["Any mental effect of the noise on the sailors","The cost of the study","The names of the ships","The size of the squadrons"],"answer_index":0,"audio":"People often argue about the effects of noise, and not all of those effects are auditory — that is, not all of them concern hearing itself. One allegation frequently made is that noise produces mental illness. A magazine once ran a dramatic picture of a distressed woman under the caption, ''Another victim, worn down to a nervous state.'' Turning to the text, the reader learned that the woman was a typist who found the clatter of office machines more and more upsetting, until at last she sought help at a psychiatric clinic. The snag in this kind of anecdote is that we cannot be sure the noise, rather than something else, was the real cause. A single story, however striking, is inadequate as proof, and a careful reader will discredit any firm conclusion drawn from it. What the question really needs is a study of large numbers of people living under noisy conditions, to discover whether they fall ill more often than others do. Some years ago a navy examined a great many men who worked on aircraft carriers, sharing the deck with squadron after squadron of jet aircraft — surely one of the noisiest workplaces on earth. Yet neither psychiatric interviews nor objective tests could show any mental effect of the noise upon these sailors. If noise harms mental health at all, the effect must be so small that present methods of diagnosis cannot find it. This does not prove that no effect exists; but it does suggest that the plea for a quieter world should rest on honest evidence, not on frightening pictures. Noise abatement is a good cause, and it is a pity to see it discredited by weak arguments. Noise may well be less dangerous than many other strains of modern life; the sensible course is to measure its effects carefully before we decide.","explanation_cn":"课文说:无论访谈还是测试,都显示不出噪声对水兵心理的任何影响。✓ no mental effect shown."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l26',4,5,26,'The Past Life of the Earth','地球的过去','强调句 It is/was + 被强调部分 + that/which、whose 引导定语从句(animals whose remains …)、被动语态(are preserved / be covered)、whether … or …(‘无论…还是…’让步)、that/which 引导定语从句指物(NCE4 无 KS 页,考点由课文结构自取;IP:源为埃罗尔·怀特《Discovery》‘地球的过去’一文,内容为‘生物遗骸如何被保存·快速掩埋’的科普事实,已用 100% 原创行文复述,去掉贝雷索夫卡猛犸的具体叙事细节,仅保留通用现象;题材=古生物科普·无害;美语化 saber/mold;第四册第26课)','地球是怎样为曾经生活在它上面的生物留下记录的呢?答案是:遗骸只有在特殊条件下才能被保存,而其中最重要的一个保存条件,就是快速掩埋。一具暴露在外的尸体很快就开始腐烂,不久便被风吹雨打毁掉,或被某种食腐动物吃掉。只有在泥浆和淤泥不断沉积的地方——海底、河床、有时是湖底——尸体才能被足够快地盖住,从而留存下来。正因如此,最有可能保存下遗骸的,是那些生活在水中或近水处的动植物。即便在那里,也只有极小一部分死去的生物,能赶在腐烂或食腐者动手之前被保存。每一种生物,无论是植物还是动物,都靠吃别的东西活着,一具尸体能逃过这命运,纯属偶然。陆生生物的遗骸更难保存,因为干燥的陆地上很少有东西能盖住它们。想想人们看到四处飞的无数鸟儿,更不用说那些几乎注意不到的小动物,如老鼠和田鼠:除了公路上,人们极少碰到一具尸体。陆生动物的痕迹一旦真的留存下来,几乎总是因为某种非常特殊的机缘。一只动物可能掉进难以到达的洞穴,或滑进冰川裂隙——正如西伯利亚的猛犸象那样——整只动物就像放进冰箱一样被保存了下来。在别处,动物会陷进天然的沥青坑,比如洛杉矶附近那些:较大的野兽为了喝水,冒险踏上看似坚实的表面,转眼就被沥青粘住;前来取食的食肉动物,也落得同样下场。对研究地球过去生命的人来说,这类地方简直是宝库。','{"q":"Listen and answer — What is the main condition for the preservation of the remains of any living creature?","options":["Quick burial, usually under water in mud or silt","Living on dry land","Being a large animal","Dying in the open air"],"answer_index":0}'::jsonb,'{"title":"强调句 It is … that / whose 定语从句 / 被动语态 / whether … or / that·which 定语从句","intro":"①强调句:It is/was + 被强调部分 + that/which + 其余,被强调的可以是名词或状语。②whose 引导定语从句,表‘…的’所属:animals whose remains are buried。③被动语态 be + 过去分词:are preserved / is destroyed。④whether … or …,‘无论…还是…’。⑤that/which 引导定语从句、指物:the creatures that die。","table":{"headers":["用法","结构","例子"],"rows":[["强调句","It is … that …","It is quick burial that preserves a body"],["whose 定语从句","名词 + whose + …","animals whose remains are buried"],["被动语态","be + 过去分词","a body is destroyed by the weather"],["whether … or","whether A or B","whether plant or animal"],["that/which 定语从句","名词 + that/which + …","the creatures that die in water"]]},"specialRules":[{"rule":"强调句强调地点、时间、方式等状语时,连接词仍用 that(不用 where/when/how)。","mark":"强调状语也用 that"},{"rule":"whether … or … 表‘无论…还是…’的让步,后半必须用 or(不用 nor/and);别与 either…or 混。","mark":"whether … or"},{"rule":"美式拼写:saber(军刀,saber-toothed 剑齿的,英式 sabre)、mold(霉,英式 mould)。本课已按美语写。","mark":"saber / mold"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l26',1,NULL,'How does the earth keep any record of the creatures that once lived on it? The answer is that remains are preserved only under special conditions, and the most important condition of preservation is quick burial.','地球是怎样为曾经生活在它上面的生物留下记录的呢?答案是:遗骸只有在特殊条件下才能被保存,而其中最重要的一个保存条件,就是快速掩埋。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l26',2,NULL,'A dead body left in the open soon begins to decompose, and before long it is destroyed by the weather or eaten by some scavenger. It is only where mud and silt are steadily laid down — on the beds of seas, rivers, and sometimes lakes — that a body can be covered over quickly enough to survive.','一具暴露在外的尸体很快就开始腐烂,不久便被风吹雨打毁掉,或被某种食腐动物吃掉。只有在泥浆和淤泥不断沉积的地方——海底、河床、有时是湖底——尸体才能被足够快地盖住,从而留存下来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l26',3,NULL,'For this reason it is animals and plants that lived in or near water whose remains are most likely to be kept. Even there, only a tiny fraction of the creatures that die are preserved before decay or scavengers do their work.','正因如此,最有可能保存下遗骸的,是那些生活在水中或近水处的动植物。即便在那里,也只有极小一部分死去的生物,能赶在腐烂或食腐者动手之前被保存。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l26',4,NULL,'Every living thing, whether it be plant or animal, lives by feeding on something else, and it is only by chance that a body escapes this fate. The remains of land creatures are far more rarely preserved, for on dry land there is seldom anything to cover them. Think of the countless birds one sees flying about, not to mention the small animals such as mice and voles that one hardly notices.','每一种生物,无论是植物还是动物,都靠吃别的东西活着,一具尸体能逃过这命运,纯属偶然。陆生生物的遗骸更难保存,因为干燥的陆地上很少有东西能盖住它们。想想人们看到四处飞的无数鸟儿,更不用说那些几乎注意不到的小动物,如老鼠和田鼠。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l26',5,NULL,'When traces of land animals do survive, it is almost always because of some very special circumstance. A creature may fall into an inaccessible cave, or slip into an ice crevasse, as the Siberian mammoths did, so that the whole animal is preserved as if in a freezer. Elsewhere, animals were trapped in natural tar pits: the larger beasts ventured onto the firm-looking surface to drink and were promptly bogged down.','陆生动物的痕迹一旦真的留存下来,几乎总是因为某种非常特殊的机缘。一只动物可能掉进难以到达的洞穴,或滑进冰川裂隙——正如西伯利亚的猛犸象那样——整只动物就像放进冰箱一样被保存了下来。在别处,动物会陷进天然的沥青坑:较大的野兽为了喝水,冒险踏上看似坚实的表面,转眼就被沥青粘住。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
