INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am4_l26_gp6','am4_l26','词汇辨析(scavenger/crevasse/silt)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l26','saber','sabre','军刀;saber-toothed 剑齿的,英式 sabre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l26','mold','mould','霉,霉菌;美语 mold,英式 mould') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l26','plow','plough','犁;美语 plow,英式 plough') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l26','skeptic','sceptic','怀疑者;美语 skeptic,英式 sceptic') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l26','set in','',NULL,'/set ɪn/','Decay soon sets in after death.','死亡后腐烂很快开始。','Winter has set in early this year.','今年冬天来得早。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l26','come across','',NULL,'/kʌm əˈkrɔːs/','You rarely come across a fossil.','你很少偶然碰到化石。','I came across an old photo yesterday.','我昨天偶然翻到一张旧照片。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l26','not to mention','',NULL,'/nɑːt tuː ˈmenʃn/','The birds, not to mention the insects, are gone.','鸟没了,更不用说昆虫了。','He speaks French, not to mention Spanish.','他会法语,更别说西班牙语了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l26','feed on','',NULL,'/fiːd ɑːn/','Scavengers feed on dead bodies.','食腐动物以尸体为食。','Owls feed on mice and voles.','猫头鹰以老鼠和田鼠为食。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp1','choice','{"stem":"\"___ is quick burial that most helps to preserve a body.\"(强调结构 __ is … that …,填句首那个形式词)","options":["This","It","There","That"],"answer_index":1,"stem_cn":"最有助于保存尸体的,是快速掩埋。","explanation_cn":"强调结构 __ is + 被强调部分 + that …;句首那个形式词是 It。✓ It is quick burial that … ✗ That / This / There:强调句句首用 It。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp1','choice','{"stem":"\"It is only in water ___ mud can cover a body quickly.\"(强调句,被强调的是地点,连接词仍用它)","options":["which","where","what","that"],"answer_index":3,"stem_cn":"只有在水里,泥浆才能迅速盖住尸体。","explanation_cn":"强调句被强调的是地点(in water),连接词仍用 that(不用 where)。✓ It is only in water that mud can cover a body. ✗ which / where / what:强调状语也用 that。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp1','choice','{"stem":"\"It was by chance ___ the mammoth was preserved.\"(强调句,被强调的是方式,连接词仍用它)","options":["when","that","which","what"],"answer_index":1,"stem_cn":"那头猛犸象得以保存,纯属偶然。","explanation_cn":"强调句被强调的是方式(by chance),连接词仍用 that(不用 how/when)。✓ It was by chance that the mammoth was preserved. ✗ which / when / what:强调状语也用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp2','choice','{"stem":"\"Animals ___ remains are buried in mud may survive.\"(定语从句,表‘它们的’所属关系,填关系词)","options":["who","which","that","whose"],"answer_index":3,"stem_cn":"遗骸被埋在泥里的动物,可能得以保存。","explanation_cn":"定语从句表‘它们的’所属关系,用 whose。✓ animals whose remains are buried. ✗ which / who / that:表所属用 whose。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp2','choice','{"stem":"\"The lake, ___ bed collected silt, preserved many shells.\"(定语从句,表‘它的’所属,填关系词)","options":["whose","that","who","which"],"answer_index":0,"stem_cn":"湖床沉积了淤泥,那湖保存了许多贝壳。","explanation_cn":"定语从句表‘它的’所属(the lake''s bed),用 whose。✓ the lake, whose bed collected silt. ✗ which / who / that:表所属用 whose。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp2','choice','{"stem":"\"Creatures ___ bodies decay quickly leave no trace.\"(定语从句,表‘它们的’所属,填关系词)","options":["which","that","whose","who"],"answer_index":2,"stem_cn":"身体腐烂得快的生物,不会留下痕迹。","explanation_cn":"定语从句表‘它们的’所属(creatures'' bodies),用 whose。✓ creatures whose bodies decay quickly. ✗ which / who / that:表所属用 whose。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp3','choice','{"stem":"\"Only a few bodies ___ preserved before decay sets in.\"(一般现在时被动,复数‘被保存’,填 be 动词)","options":["have","being","is","are"],"answer_index":3,"stem_cn":"只有少数尸体在腐烂前被保存下来。","explanation_cn":"一般现在时被动 be + 过去分词;复数、现在时用 are。✓ a few bodies are preserved. ✗ is(单数)/ have / being:复数现在被动用 are。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp3','choice','{"stem":"\"A dead body is soon ___ by the weather.\"(被动语态,‘被毁掉’,填‘毁掉’那个动词的过去分词)","options":["destroys","destroy","destroyed","destroying"],"answer_index":2,"stem_cn":"尸体很快就被风吹雨打毁掉。","explanation_cn":"被动语态 be + 过去分词,‘被毁掉’;填‘毁掉’那个动词的过去分词 destroyed。✓ is soon destroyed by the weather. ✗ destroying(主动)/ destroys / destroy:被动用过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp3','choice','{"stem":"\"The mammoth was ___ in the ice for thousands of years.\"(被动语态,‘被保存’,填‘保存’那个动词的过去分词)","options":["preserving","preserved","preserve","preserves"],"answer_index":1,"stem_cn":"那头猛犸象在冰中保存了数千年。","explanation_cn":"被动语态 be + 过去分词,‘被保存’;填‘保存’那个动词的过去分词 preserved。✓ was preserved in the ice. ✗ preserving(主动)/ preserves / preserve:被动用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp4','choice','{"stem":"\"Every creature, ___ plant or animal, feeds on something else.\"(‘无论…还是…’,填让步连词)","options":["though","neither","whether","either"],"answer_index":2,"stem_cn":"每一种生物,无论是植物还是动物,都以别的东西为食。","explanation_cn":"‘无论…还是…’的让步,前一半用 whether。✓ whether plant or animal. ✗ either / neither / though:‘无论…还是’用 whether。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp4','choice','{"stem":"\"Whether dead ___ alive, a body may be eaten by scavengers.\"(‘无论…还是…’,与 whether 呼应,填后一半)","options":["or","and","but","nor"],"answer_index":0,"stem_cn":"无论死活,尸体都可能被食腐动物吃掉。","explanation_cn":"‘无论…还是…’,与前面 Whether 呼应,后半用 or。✓ Whether dead or alive. ✗ nor / and / but:与 whether 呼应用 or。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp4','choice','{"stem":"\"The remains, ___ of fish or of birds, are rarely found.\"(‘无论…还是…’,填让步连词)","options":["either","neither","whether","if"],"answer_index":2,"stem_cn":"无论是鱼还是鸟的遗骸,都很少被发现。","explanation_cn":"‘无论…还是…’的让步,用 whether。✓ whether of fish or of birds. ✗ either / neither / if:‘无论…还是’用 whether。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp5','choice','{"stem":"\"The creatures ___ die in water are more often preserved.\"(定语从句,指物,在从句里作主语,填关系词)","options":["that","whose","who","whom"],"answer_index":0,"stem_cn":"在水里死去的生物更常被保存。","explanation_cn":"定语从句指物、在从句里作主语,用 that(也可用 which)。✓ the creatures that die in water. ✗ who / whose / whom:指物作主语用 that。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp5','choice','{"stem":"\"Think of the birds ___ one sees flying about.\"(定语从句,指物,在从句里作宾语,填关系词)","options":["whose","that","whom","who"],"answer_index":1,"stem_cn":"想想人们看到四处飞的那些鸟。","explanation_cn":"定语从句指物、在从句里作宾语,用 that(也可用 which)。✓ the birds that one sees. ✗ who / whose / whom:指物用 that。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp5','choice','{"stem":"\"The mud ___ covers a body must be laid down fast.\"(定语从句,指物,在从句里作主语,填关系词)","options":["that","whom","who","whose"],"answer_index":0,"stem_cn":"盖住尸体的泥浆,必须迅速沉积下来。","explanation_cn":"定语从句指物、在从句里作主语,用 that(也可用 which)。✓ the mud that covers a body. ✗ who / whose / whom:指物作主语用 that。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp6','choice','{"stem":"\"An animal that feeds on dead bodies is a ___.\"(“食腐动物”用哪个词)","options":["teacher","traveler","gardener","scavenger"],"answer_index":3,"stem_cn":"以尸体为食的动物。","explanation_cn":"以死尸为食的动物是 scavenger(食腐动物)。✓ an animal that feeds on dead bodies is a scavenger. ✗ gardener 园丁;✗ traveler 旅行者;✗ teacher 老师——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp6','choice','{"stem":"\"A deep open crack in ice or rock is a ___.\"(“(冰/岩)裂隙”用哪个词)","options":["harbor","crevasse","ceiling","meadow"],"answer_index":1,"stem_cn":"冰面或岩石上又深又险的裂缝。","explanation_cn":"冰面或岩石上又深又敞的裂隙是 crevasse。✓ a deep open crack in ice is a crevasse. ✗ meadow 草地;✗ harbor 港口;✗ ceiling 天花板——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',5,'am4_l26_gp6','choice','{"stem":"\"Fine sand and earth carried by water is ___.\"(“淤泥”用哪个词)","options":["stone","steam","smoke","silt"],"answer_index":3,"stem_cn":"由水携带的细沙与泥土。","explanation_cn":"由水携带、沉积下来的细沙与泥土是 silt(淤泥)。✓ fine sand and earth carried by water is silt. ✗ steam 蒸汽;✗ smoke 烟;✗ stone 石头——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"preservation 的意思是:","options":["破坏","保存,保护","污染","腐烂"],"answer_index":1,"explanation_cn":"preservation = 保存、保护。✓ the most important condition of preservation."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"scavenger 的意思是:","options":["食草动物","捕食者","寄生虫","食腐动物"],"answer_index":3,"explanation_cn":"scavenger = 食腐动物。✓ eaten by some scavenger."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"decompose 的意思是:","options":["腐烂,分解","冻结","生长","燃烧"],"answer_index":0,"explanation_cn":"decompose = 腐烂、分解。✓ a dead body begins to decompose."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"inaccessible 的意思是:","options":["宽敞的","显而易见的","难以到达的","常见的"],"answer_index":2,"explanation_cn":"inaccessible = 难以到达的。✓ fall into an inaccessible cave."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"crevasse 的意思是:","options":["山峰","平原","河口","(冰川)裂隙"],"answer_index":3,"explanation_cn":"crevasse = (冰川)裂隙。✓ slip into an ice crevasse."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',6,NULL,'choice','{"stem":"venture 的意思是:","options":["躲避","返回","冒险前往,敢于","停留"],"answer_index":2,"explanation_cn":"venture = 冒险前往、敢于。✓ ventured onto the firm-looking surface."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',7,NULL,'cloze','{"stem":"第 1 空","context":"Remains are preserved only by quick burial. It is in seas and lakes ___1___ mud and silt cover a body fast. Animals ___2___ remains lie in the mud may survive, but only a small ___3___ of all creatures are kept, ___4___ they be plant or animal.","blank_no":1,"options":["that","which","where","what"],"answer_index":0,"explanation_cn":"强调句被强调的是地点,连接词用 that。✓ It is in seas and lakes that mud covers a body fast."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',7,NULL,'cloze','{"stem":"第 2 空","context":"Remains are preserved only by quick burial. It is in seas and lakes ___1___ mud and silt cover a body fast. Animals ___2___ remains lie in the mud may survive, but only a small ___3___ of all creatures are kept, ___4___ they be plant or animal.","blank_no":2,"options":["whose","which","who","that"],"answer_index":0,"explanation_cn":"定语从句表‘它们的’所属,用 whose。✓ animals whose remains lie in the mud."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',7,NULL,'cloze','{"stem":"第 3 空","context":"Remains are preserved only by quick burial. It is in seas and lakes ___1___ mud and silt cover a body fast. Animals ___2___ remains lie in the mud may survive, but only a small ___3___ of all creatures are kept, ___4___ they be plant or animal.","blank_no":3,"options":["fraction","distance","motion","station"],"answer_index":0,"explanation_cn":"‘一小部分’是 fraction。✓ only a small fraction of all creatures."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',7,NULL,'cloze','{"stem":"第 4 空","context":"Remains are preserved only by quick burial. It is in seas and lakes ___1___ mud and silt cover a body fast. Animals ___2___ remains lie in the mud may survive, but only a small ___3___ of all creatures are kept, ___4___ they be plant or animal.","blank_no":4,"options":["whether","either","neither","though"],"answer_index":0,"explanation_cn":"‘无论…还是…’的让步,用 whether。✓ whether they be plant or animal."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',8,NULL,'choice','{"stem":"What is the main condition for the preservation of a creature''s remains?","options":["Living on dry land","Quick burial, usually under water in mud or silt","Dying in the open air","Being a large animal"],"answer_index":1,"explanation_cn":"录音说:任何生物遗骸得以保存的首要条件,是快速掩埋——通常是在水下的泥浆或淤泥中。✓ quick burial under water."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',8,NULL,'choice','{"stem":"Why are the remains of land animals so rarely preserved?","options":["They are always eaten by birds","Land animals never die","On dry land there is seldom anything to cover them before they decay","They are too small to see"],"answer_index":2,"explanation_cn":"录音说:陆生动物遗骸罕有保存,因为干燥陆地上很少有东西能在腐烂前把它们盖住。✓ nothing to cover them on land."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',8,NULL,'choice','{"stem":"How were the Siberian mammoths preserved so completely?","options":["They fell into ice crevasses and were kept as if in a freezer","They lived in the sea","They were buried by people","They were made of stone"],"answer_index":0,"explanation_cn":"录音说:西伯利亚的猛犸象掉进冰川裂隙,整只动物像放进冰箱一样被保存下来。✓ ice crevasse, like a freezer."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',9,NULL,'choice','{"stem":"你想说\"最有助于保存尸体的,是快速掩埋\"(强调句 It is … that):","options":["Is quick burial that best preserves a body.","It is quick burial that best preserves a body.","It is quick burial what best preserves a body.","It quick burial is that best preserves a body."],"answer_index":1,"explanation_cn":"强调结构 It is … that …;被强调的 quick burial 放在 It is 和 that 之间,不能省 It(不写 Is quick burial…)、连接词用 that(不用 what)、语序不能打乱(不写 It quick burial is that…)。✓ It is quick burial that … 场合:突出强调某一部分。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',9,NULL,'choice','{"stem":"你想说\"尸体很快就被风雨毁掉\"(被动语态):","options":["A dead body is soon destroy by the weather.","A dead body is soon destroying by the weather.","A dead body is soon destroyed by the weather.","A dead body soon destroys by the weather."],"answer_index":2,"explanation_cn":"被动语态 be + 过去分词:is + destroyed;用过去分词 destroyed(不写原形 destroy、不写 -ing、也不缺 be 而写成主动 destroys)。✓ is destroyed by … 场合:说“某物被…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',9,NULL,'choice','{"stem":"你想说\"每种生物,无论是植物还是动物,都以别物为食\"(whether … or …):","options":["Every creature, whether plant or animal, feeds on something else.","Every creature, whatever plant or animal, feeds on something else.","Every creature, whether plant and animal, feeds on something else.","Every creature, whether plant nor animal, feeds on something else."],"answer_index":0,"explanation_cn":"whether … or … 表‘无论…还是…’;前用 whether、后用 or(不用 nor/and)、不用 whatever 替换 whether。✓ whether plant or animal. 场合:说“无论是…还是…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"scavenger 的意思是:","options":["食草动物","寄生虫","食腐动物","捕食者"],"answer_index":2,"explanation_cn":"scavenger = 食腐动物。✓ eaten by some scavenger."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"crevasse 的意思是:","options":["河口","(冰川)裂隙","平原","山峰"],"answer_index":1,"explanation_cn":"crevasse = (冰川)裂隙。✓ slip into an ice crevasse."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"\"___ is quick burial that most helps to preserve a body.\"(强调结构 __ is … that,填句首的形式词)","options":["There","That","This","It"],"answer_index":3,"stem_cn":"最有助于保存尸体的,是快速掩埋。","explanation_cn":"强调结构 __ is … that,句首那个形式词是 It。✓ It is quick burial that … ✗ That / This / There。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"\"Every creature, ___ plant or animal, feeds on something else.\"(‘无论…还是…’,填让步连词)","options":["neither","either","whether","though"],"answer_index":2,"stem_cn":"每种生物,无论植物还是动物,都以别物为食。","explanation_cn":"‘无论…还是…’的让步,用 whether。✓ whether plant or animal. ✗ either / neither / though。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"\"set in\" 的意思是:","options":["(天气/坏情况)开始并持续","坐下","出发","放弃"],"answer_index":0,"explanation_cn":"set in = (天气或不好的情况)开始并持续。✓ decay soon sets in."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"\"come across\" 的意思是:","options":["故意寻找","反复练习","完全避开","偶然遇到/发现"],"answer_index":3,"explanation_cn":"come across = 偶然遇到、偶然发现。✓ you rarely come across a fossil."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"According to the passage, where are remains most likely to be preserved?","options":["On busy roads","In dry open fields","In seas, rivers, and lakes, where mud is quickly deposited","High in the mountains"],"answer_index":2,"passage":"How does the earth keep any record of the creatures that once lived on it? The answer is that remains are preserved only under special conditions, and the most important condition of preservation is quick burial. A dead body left in the open soon begins to decompose, and before long it is destroyed by the weather or eaten by some scavenger. It is only where mud and silt are steadily laid down — on the beds of seas, rivers, and sometimes lakes — that a body can be covered over quickly enough to survive. For this reason it is animals and plants that lived in or near water whose remains are most likely to be kept. Even there, only a tiny fraction of the creatures that die are preserved before decay or scavengers do their work. Every living thing, whether it be plant or animal, lives by feeding on something else, and it is only by chance that a body escapes this fate. The remains of land creatures are far more rarely preserved, for on dry land there is seldom anything to cover them. Think of the countless birds one sees flying about, not to mention the small animals such as mice and voles that one hardly notices: it is very rare to come across a dead one, except on the roads. When traces of land animals do survive, it is almost always because of some very special circumstance. A creature may fall into an inaccessible cave, or slip into an ice crevasse, as the Siberian mammoths did, so that the whole animal is preserved as if in a freezer. Elsewhere, animals were trapped in natural tar pits, like those near Los Angeles: the larger beasts ventured onto the firm-looking surface to drink and were promptly bogged down, and the carnivores that came to feed on them met the same fate.","explanation_cn":"课文说:遗骸最可能保存在海、河、湖里,那里泥沙不断快速沉积,能迅速盖住尸体。✓ seas, rivers, lakes."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"Why do the remains of land animals so seldom survive?","options":["They are all eaten by mammoths","The weather protects them","Land animals do not really die","On land there is rarely anything to bury them before they decay"],"answer_index":3,"passage":"How does the earth keep any record of the creatures that once lived on it? The answer is that remains are preserved only under special conditions, and the most important condition of preservation is quick burial. A dead body left in the open soon begins to decompose, and before long it is destroyed by the weather or eaten by some scavenger. It is only where mud and silt are steadily laid down — on the beds of seas, rivers, and sometimes lakes — that a body can be covered over quickly enough to survive. For this reason it is animals and plants that lived in or near water whose remains are most likely to be kept. Even there, only a tiny fraction of the creatures that die are preserved before decay or scavengers do their work. Every living thing, whether it be plant or animal, lives by feeding on something else, and it is only by chance that a body escapes this fate. The remains of land creatures are far more rarely preserved, for on dry land there is seldom anything to cover them. Think of the countless birds one sees flying about, not to mention the small animals such as mice and voles that one hardly notices: it is very rare to come across a dead one, except on the roads. When traces of land animals do survive, it is almost always because of some very special circumstance. A creature may fall into an inaccessible cave, or slip into an ice crevasse, as the Siberian mammoths did, so that the whole animal is preserved as if in a freezer. Elsewhere, animals were trapped in natural tar pits, like those near Los Angeles: the larger beasts ventured onto the firm-looking surface to drink and were promptly bogged down, and the carnivores that came to feed on them met the same fate.","explanation_cn":"课文说:陆生动物遗骸罕见,因为陆地上很少有东西在腐烂前把它们盖住。✓ nothing to cover on land."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"How were whole Siberian mammoths preserved?","options":["They were buried by early people","They turned to tar","They fell into ice crevasses and were frozen as if in a refrigerator","They were dried in the sun"],"answer_index":2,"audio":"How does the earth keep any record of the creatures that once lived on it? The answer is that remains are preserved only under special conditions, and the most important condition of preservation is quick burial. A dead body left in the open soon begins to decompose, and before long it is destroyed by the weather or eaten by some scavenger. It is only where mud and silt are steadily laid down — on the beds of seas, rivers, and sometimes lakes — that a body can be covered over quickly enough to survive. For this reason it is animals and plants that lived in or near water whose remains are most likely to be kept. Even there, only a tiny fraction of the creatures that die are preserved before decay or scavengers do their work. Every living thing, whether it be plant or animal, lives by feeding on something else, and it is only by chance that a body escapes this fate. The remains of land creatures are far more rarely preserved, for on dry land there is seldom anything to cover them. Think of the countless birds one sees flying about, not to mention the small animals such as mice and voles that one hardly notices: it is very rare to come across a dead one, except on the roads. When traces of land animals do survive, it is almost always because of some very special circumstance. A creature may fall into an inaccessible cave, or slip into an ice crevasse, as the Siberian mammoths did, so that the whole animal is preserved as if in a freezer. Elsewhere, animals were trapped in natural tar pits, like those near Los Angeles: the larger beasts ventured onto the firm-looking surface to drink and were promptly bogged down, and the carnivores that came to feed on them met the same fate.","explanation_cn":"课文说:西伯利亚猛犸象滑进冰川裂隙,整只被冻存,如同放进冰箱。✓ ice crevasse, frozen."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l26',10,NULL,'choice','{"stem":"What is the single most important condition for preservation?","options":["Quick burial before decay or scavengers act","Living near a city","Being a plant","Having strong bones"],"answer_index":0,"audio":"How does the earth keep any record of the creatures that once lived on it? The answer is that remains are preserved only under special conditions, and the most important condition of preservation is quick burial. A dead body left in the open soon begins to decompose, and before long it is destroyed by the weather or eaten by some scavenger. It is only where mud and silt are steadily laid down — on the beds of seas, rivers, and sometimes lakes — that a body can be covered over quickly enough to survive. For this reason it is animals and plants that lived in or near water whose remains are most likely to be kept. Even there, only a tiny fraction of the creatures that die are preserved before decay or scavengers do their work. Every living thing, whether it be plant or animal, lives by feeding on something else, and it is only by chance that a body escapes this fate. The remains of land creatures are far more rarely preserved, for on dry land there is seldom anything to cover them. Think of the countless birds one sees flying about, not to mention the small animals such as mice and voles that one hardly notices: it is very rare to come across a dead one, except on the roads. When traces of land animals do survive, it is almost always because of some very special circumstance. A creature may fall into an inaccessible cave, or slip into an ice crevasse, as the Siberian mammoths did, so that the whole animal is preserved as if in a freezer. Elsewhere, animals were trapped in natural tar pits, like those near Los Angeles: the larger beasts ventured onto the firm-looking surface to drink and were promptly bogged down, and the carnivores that came to feed on them met the same fate.","explanation_cn":"课文说:保存的头号条件是快速掩埋,赶在腐烂或食腐者动手之前。✓ quick burial."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
